nce":"ASTM D6709","standard_body":"ASTM","method_title":"Sequence VIII Engine Test","applies_to_business_line":"Lubricants"},{"source_method_name":"Sequence IVA","governed_standard_reference":"ASTM D6891","standard_body":"ASTM","method_title":"Sequence IVA Engine Test","applies_to_business_line":"Lubricants"},{"source_method_name":"Sequence IIIF","governed_standard_reference":"ASTM D6984","standard_body":"ASTM","method_title":"Sequence IIIF Engine Test","applies_to_business_line":"Lubricants"},{"source_method_name":"Deposit Sequence","governed_standard_reference":"ASTM D6593","standard_body":"ASTM","method_title":"Sequence VG Engine Test for Deposit Formation","applies_to_business_line":"Lubricants"},{"source_method_name":"ROBO Oxidation","governed_standard_reference":"ASTM D7528","standard_body":"ASTM","method_title":"ROBO Apparatus Oxidation Test","applies_to_business_line":"Lubricants"},{"source_method_name":"PDSC Oxidation","governed_standard_reference":"ASTM D6186","standard_body":"ASTM","method_title":"Oxidation Induction Time by PDSC","applies_to_business_line":"Lubricants"},{"source_method_name":"Injector Fouling","governed_standard_reference":"ASTM D6421","standard_body":"ASTM","method_title":"Electronic Port Fuel Injector Fouling","applies_to_business_line":"Fuels"},{"source_method_name":"Water Reaction Aviation Fuel","governed_standard_reference":"ASTM D1094","standard_body":"ASTM","method_title":"Water Reaction of Aviation Fuels","applies_to_business_line":"Fuels"},{"source_method_name":"ILSAC GF-6","governed_standard_reference":"ILSAC GF-6","standard_body":"ILSAC","method_title":"Passenger Car Engine Oil Performance Specification","applies_to_business_line":"Lubricants"},{"source_method_name":"API SP","governed_standard_reference":"API SP","standard_body":"API","method_title":"API Service Category SP","applies_to_business_line":"Lubricants"}]'::jsonb) AS method(source_method_name text, governed_standard_reference text)
            UNION
            SELECT DISTINCT lower(governed_standard_reference), governed_standard_reference
            FROM jsonb_to_recordset('[{"source_method_name":"Viscosity","governed_standard_reference":"ASTM D445","standard_body":"ASTM","method_title":"Kinematic Viscosity of Transparent and Opaque Liquids","applies_to_business_line":"Lubricants"},{"source_method_name":"Kinematic Viscosity","governed_standard_reference":"ASTM D445","standard_body":"ASTM","method_title":"Kinematic Viscosity of Transparent and Opaque Liquids","applies_to_business_line":"Lubricants"},{"source_method_name":"Kinematic Viscosity @ 100C","governed_standard_reference":"ASTM D445","standard_body":"ASTM","method_title":"Kinematic Viscosity of Transparent and Opaque Liquids","applies_to_business_line":"Lubricants"},{"source_method_name":"KV100","governed_standard_reference":"ASTM D445","standard_body":"ASTM","method_title":"Kinematic Viscosity of Transparent and Opaque Liquids","applies_to_business_line":"Lubricants"},{"source_method_name":"Visc @ 40C","governed_standard_reference":"ASTM D445","standard_body":"ASTM","method_title":"Kinematic Viscosity of Transparent and Opaque Liquids","applies_to_business_line":"Lubricants"},{"source_method_name":"Flash Point","governed_standard_reference":"ASTM D93","standard_body":"ASTM","method_title":"Flash Point by Pensky-Martens Closed Cup","applies_to_business_line":"Fuels"},{"source_method_name":"Flash Pt","governed_standard_reference":"ASTM D93","standard_body":"ASTM","method_title":"Flash Point by Pensky-Martens Closed Cup","applies_to_business_line":"Fuels"},{"source_method_name":"Flash Point PMCC","governed_standard_reference":"ASTM D93","standard_body":"ASTM","method_title":"Flash Point by Pensky-Martens Closed Cup","applies_to_business_line":"Fuels"},{"source_method_name":"Flash Point COC","governed_standard_reference":"ASTM D92","standard_body":"ASTM","method_title":"Flash Point by Cleveland Open Cup","applies_to_business_line":"Lubricants"},{"source_method_name":"Flash Point Open Cup","governed_standard_reference":"ASTM D92","standard_body":"ASTM","method_title":"Flash Point by Cleveland Open Cup","applies_to_business_line":"Lubricants"},{"source_method_name":"Pour Point","governed_standard_reference":"ASTM D97","standard_body":"ASTM","method_title":"Pour Point of Petroleum Products","applies_to_business_line":"Lubricants"},{"source_method_name":"Acid Number","governed_standard_reference":"ASTM D664","standard_body":"ASTM","method_title":"Acid Number by Potentiometric Titration","applies_to_business_line":"Lubricants"},{"source_method_name":"Total Acid Number","governed_standard_reference":"ASTM D664","standard_body":"ASTM","method_title":"Acid Number by Potentiometric Titration","applies_to_business_line":"Lubricants"},{"source_method_name":"TAN","governed_standard_reference":"ASTM D664","standard_body":"ASTM","method_title":"Acid Number by Potentiometric Titration","applies_to_business_line":"Lubricants"},{"source_method_name":"Base Number","governed_standard_reference":"ASTM D4739","standard_body":"ASTM","method_title":"Base Number by Potentiometric Hydrochloric Acid Titration","applies_to_business_line":"Lubricants"},{"source_method_name":"TBN","governed_standard_reference":"ASTM D4739","standard_body":"ASTM","method_title":"Base Number by Potentiometric Hydrochloric Acid Titration","applies_to_business_line":"Lubricants"},{"source_method_name":"Sulfur","governed_standard_reference":"ASTM D2622","standard_body":"ASTM","method_title":"Sulfur by Wavelength Dispersive XRF","applies_to_business_line":"Fuels"},{"source_method_name":"Sulphur Content","governed_standard_reference":"ASTM D2622","standard_body":"ASTM","method_title":"Sulfur by Wavelength Dispersive XRF","applies_to_business_line":"Fuels"},{"source_method_name":"Sulfur XRF","governed_standard_reference":"ASTM D4294","standard_body":"ASTM","method_title":"Sulfur by Energy Dispersive XRF","applies_to_business_line":"Fuels"},{"source_method_name":"Sulfur EDXRF","governed_standard_reference":"ASTM D4294","standard_body":"ASTM","method_title":"Sulfur by Energy Dispersive XRF","applies_to_business_line":"Fuels"},{"source_method_name":"Density","governed_standard_reference":"ASTM D4052","standard_body":"ASTM","method_title":"Density, Relative Density, and API Gravity by Digital Density Meter","applies_to_business_line":"Fuels"},{"source_method_name":"API Gravity","governed_standard_reference":"ASTM D4052","standard_body":"ASTM","method_title":"Density, Relative Density, and API Gravity by Digital Density Meter","applies_to_business_line":"Fuels"},{"source_method_name":"Water Content","governed_standard_reference":"ASTM D6304","standard_body":"ASTM","method_title":"Water by Coulometric Karl Fischer Titration","applies_to_business_line":"Cross-business"},{"source_method_name":"Karl Fischer Water","governed_standard_reference":"ASTM D6304","standard_body":"ASTM","method_title":"Water by Coulometric Karl Fischer Titration","applies_to_business_line":"Cross-business"},{"source_method_name":"Ash","governed_standard_reference":"ASTM D482","standard_body":"ASTM","method_title":"Ash from Petroleum Products","applies_to_business_line":"Cross-business"},{"source_method_name":"Viscosity Index","governed_standard_reference":"ASTM D2270","standard_body":"ASTM","method_title":"Calculating Viscosity Index from Kinematic Viscosity","applies_to_business_line":"Lubricants"},{"source_method_name":"VI","governed_standard_reference":"ASTM D2270","standard_body":"ASTM","method_title":"Calculating Viscosity Index from Kinematic Viscosity","applies_to_business_line":"Lubricants"},{"source_method_name":"Cold Crank","governed_standard_reference":"ASTM D5293","standard_body":"ASTM","method_title":"Apparent Viscosity by Cold-Cranking Simulator","applies_to_business_line":"Lubricants"},{"source_method_name":"CCS","governed_standard_reference":"ASTM D5293","standard_body":"ASTM","method_title":"Apparent Viscosity by Cold-Cranking Simulator","applies_to_business_line":"Lubricants"},{"source_method_name":"Wear Metals","governed_standard_reference":"ASTM D5185","standard_body":"ASTM","method_title":"Multielement Determination by ICP-AES","applies_to_business_line":"Lubricants"},{"source_method_name":"ICP Metals","governed_standard_reference":"ASTM D5185","standard_body":"ASTM","method_title":"Multielement Determination by ICP-AES","applies_to_business_line":"Lubricants"},{"source_method_name":"Cloud Point","governed_standard_reference":"ASTM D2500","standard_body":"ASTM","method_title":"Cloud Point of Petroleum Products","applies_to_business_line":"Fuels"},{"source_method_name":"Color","governed_standard_reference":"ASTM D1500","standard_body":"ASTM","method_title":"ASTM Color of Petroleum Products","applies_to_business_line":"Cross-business"},{"source_method_name":"Oxidation Stability","governed_standard_reference":"ASTM D2274","standard_body":"ASTM","method_title":"Oxidation Stability of Distillate Fuel Oil","applies_to_business_line":"Fuels"},{"source_method_name":"Aniline Point","governed_standard_reference":"ASTM D611","standard_body":"ASTM","method_title":"Aniline Point and Mixed Aniline Point","applies_to_business_line":"Fuels"},{"source_method_name":"Bromine Number","governed_standard_reference":"ASTM D1159","standard_body":"ASTM","method_title":"Bromine Numbers by Electrometric Titration","applies_to_business_line":"Chemicals"},{"source_method_name":"Boiling Range Distribution","governed_standard_reference":"ASTM D2887","standard_body":"ASTM","method_title":"Boiling Range Distribution by Gas Chromatography","applies_to_business_line":"Fuels"},{"source_method_name":"SimDis","governed_standard_reference":"ASTM D2887","standard_body":"ASTM","method_title":"Boiling Range Distribution by Gas Chromatography","applies_to_business_line":"Fuels"},{"source_method_name":"Cetane Index","governed_standard_reference":"ASTM D976","standard_body":"ASTM","method_title":"Calculated Cetane Index of Distillate Fuels","applies_to_business_line":"Fuels"},{"source_method_name":"Sequence VIII","governed_standard_reference":"ASTM D6709","standard_body":"ASTM","method_title":"Sequence VIII Engine Test","applies_to_business_line":"Lubricants"},{"source_method_name":"Sequence IVA","governed_standard_reference":"ASTM D6891","standard_body":"ASTM","method_title":"Sequence IVA Engine Test","applies_to_business_line":"Lubricants"},{"source_method_name":"Sequence IIIF","governed_standard_reference":"ASTM D6984","standard_body":"ASTM","method_title":"Sequence IIIF Engine Test","applies_to_business_line":"Lubricants"},{"source_method_name":"Deposit Sequence","governed_standard_reference":"ASTM D6593","standard_body":"ASTM","method_title":"Sequence VG Engine Test for Deposit Formation","applies_to_business_line":"Lubricants"},{"source_method_name":"ROBO Oxidation","governed_standard_reference":"ASTM D7528","standard_body":"ASTM","method_title":"ROBO Apparatus Oxidation Test","applies_to_business_line":"Lubricants"},{"source_method_name":"PDSC Oxidation","governed_standard_reference":"ASTM D6186","standard_body":"ASTM","method_title":"Oxidation Induction Time by PDSC","applies_to_business_line":"Lubricants"},{"source_method_name":"Injector Fouling","governed_standard_reference":"ASTM D6421","standard_body":"ASTM","method_title":"Electronic Port Fuel Injector Fouling","applies_to_business_line":"Fuels"},{"source_method_name":"Water Reaction Aviation Fuel","governed_standard_reference":"ASTM D1094","standard_body":"ASTM","method_title":"Water Reaction of Aviation Fuels","applies_to_business_line":"Fuels"},{"source_method_name":"ILSAC GF-6","governed_standard_reference":"ILSAC GF-6","standard_body":"ILSAC","method_title":"Passenger Car Engine Oil Performance Specification","applies_to_business_line":"Lubricants"},{"source_method_name":"API SP","governed_standard_reference":"API SP","standard_body":"API","method_title":"API Service Category SP","applies_to_business_line":"Lubricants"}]'::jsonb) AS method(governed_standard_reference text)
          ),
          material_ref AS (
            SELECT material_key,
              lower(clinton_material_code) clinton_material,
              lower(houston_material_id) houston_material
            FROM silver.conformed_material
          ),
          clinton AS (
            SELECT row_number() OVER () record_id, c.source_row_number,
              material.material_key, method.governed_standard_reference test_method,
              'MTH_' || md5(method.governed_standard_reference) test_method_key,
              c.site_code, c.product_line business_line, c.date_completed completed_at,
              c.date_requested requested_at, c.sample_status
            FROM silver."silver_lims_clinton_nj" c
            LEFT JOIN material_ref material ON material.clinton_material = lower(c.material_code)
            LEFT JOIN method_ref method ON method.source_method_name = lower(c.test_type)
          ),
          houston AS (
            SELECT row_number() OVER () record_id, h.source_row_number,
              material.material_key, method.governed_standard_reference test_method,
              'MTH_' || md5(method.governed_standard_reference) test_method_key,
              h.location site_code, h.business_line, h.comp_date completed_at,
              h.req_date requested_at, h.status sample_status
            FROM silver."silver_lims_houston" h
            LEFT JOIN material_ref material ON material.houston_material = lower(h.material_id)
            LEFT JOIN method_ref method ON method.source_method_name = lower(h.analysis_type)
          ),
          matches AS (
            SELECT c.record_id clinton_id, h.record_id houston_id
            FROM clinton c JOIN houston h
              ON c.material_key = h.material_key
             AND c.test_method = h.test_method
             AND abs(extract(epoch FROM (c.completed_at - h.completed_at))) <= 259200
          ),
          resolved AS (
            SELECT 'SMP_' || md5('cross-site:' || c.source_row_number || ':' || h.source_row_number) lab_sample_key,
              c.material_key, c.test_method_key, c.site_code, c.business_line, c.completed_at,
              c.requested_at, c.sample_status, 2 source_system_count
            FROM matches m JOIN clinton c ON c.record_id = m.clinton_id JOIN houston h ON h.record_id = m.houston_id
            UNION ALL
            SELECT 'SMP_' || md5('clinton:' || c.source_row_number), c.material_key, c.test_method_key,
              c.site_code, c.business_line, c.completed_at, c.requested_at, c.sample_status, 1
            FROM clinton c WHERE NOT EXISTS (SELECT 1 FROM matches m WHERE m.clinton_id = c.record_id)
            UNION ALL
            SELECT 'SMP_' || md5('houston:' || h.source_row_number), h.material_key, h.test_method_key,
              h.site_code, h.business_line, h.completed_at, h.requested_at, h.sample_status, 1
            FROM houston h WHERE NOT EXISTS (SELECT 1 FROM matches m WHERE m.houston_id = h.record_id)
          )
          INSERT INTO silver.conformed_lab_sample (
            lab_sample_key, material_key, test_method_key, site_code, business_line, completion_date,
            requested_date, sample_status, source_system_count
          )
          SELECT * FROM resolved;
